"""Recognise missing observations and distinguish an inference from a guess."""
import re


def limitation(text):
    q = text.casefold().replace("ё","е")
    missing = re.search(r"не (?:сказа|говори|упомян|сообщ|видел|видно|знаю|расска|указа)|неизвестн|нет (?:данных|сведений|термометра|измер)|без (?:данных|сведений|измерений|термометра)|других сведений",q)
    private = re.search(r"\b(?:мой|мо[яюеий]|моем|моей|моего|мою|твоей|у меня|у нас|за моей|сейчас у)\b",q)
    withheld = re.search(r"\b(?:не скажу|не покажу|не видно|не видел\w*|никто не видел|не смотрел\w*|не открыва\w*|не заглядыва\w*|не говорил\w*|не называл\w*|не (?:могу|можешь) (?:видеть|показать)|не сообщ\w*|без (?:единой )?(?:подсказк\w*|фотограф\w*|сведен\w*)|вслепую|случайно|наугад|закрытыми глазами)\b",q)
    if (withheld or missing) and re.search(r"\b(?:какой|какая|какое|котор\w*|что (?:там|внутри|лежит|написано)|назови|определи|скажи|угада\w*|чем закончит\w*)\b",q) and not re.search(r"как (?:мне|легче|лучше)|совет|вероятност|придумай|представь",q):
        if re.search(r"записк|букв|листк|текст|надпис|конверт",q):
            return "Прочесть это по описанию не получится. Нужно увидеть саму надпись или услышать её от того, кто прочитал."
        if re.search(r"брос\w*|монет|жреби|кости|куби[кч]|случай|наугад",q) and not re.search(r"цвет",q):
            return "Исход заранее не известен. Для ответа нужно увидеть, что действительно выпало."
        if re.search(r"карман|коробк|сумк|рюкзак|пакет|ящик|ладон|шкатул",q) and not re.search(r"цвет",q):
            return "Снаружи содержимое не видно. Пока никто не посмотрел внутрь, я могу лишь придумать версию."
    if re.search(r"\b(?:что|кто)\b",q) and re.search(r"\b(?:думает|подумал\w*|задумал\w*|загадал\w*|чувствует|на уме)\b",q) and (missing or re.search(r"точно|наверняка|уверен|не сказа",q)):
        return "Наверняка это знает только сам человек. Без его слов я бы выдал свою догадку за чужую мысль."
    if (missing or withheld) and re.search(r"\b(?:где|куда)\b",q) and re.search(r"полож|лежит|спрят|остав|убрал|перелож",q):
        return "Место в рассказе не указано. Надёжнее восстановить, где эту вещь видели в последний раз."
    if re.search(r"температур|градус|термометр|влажност",q) and (private or missing) and not re.search(r"почему|поставить|настроить",q):
        measure = "гигрометра" if "влажност" in q else "термометра"
        return f"Точного значения у меня нет. Нужны показания {measure} именно в этом месте."
    if re.search(r"какого (?:же |точно |именно )?цвета|цвет (?:этого|моей)|как\w* цвет",q) and (missing or private):
        return "Цвет по этому описанию не определить. Тут помог бы взгляд на сам предмет или на его фотографию."
    if missing and re.search(r"\b(?:выбер\w*|выбери|котор\w*|какой)\b",q) and re.search(r"правильн|верн|отлича|подход",q):
        return "Сведений для выбора не хватает. Пока неизвестно, чем отличаются варианты, любой из них был бы догадкой."
    if re.search(r"как зовут|назови имя|какое имя|как\w* фамили",q) and (private or missing):
        return "Имя в рассказе не прозвучало. Узнать его можно у самого человека, а угадать надёжно не получится."
    if re.search(r"загадал|мысленно|чита\w* мысли|о чем я думаю",q) and not re.search(r"если бы|научи|что если",q):
        return "Ты знаешь ответ, а у меня пока нет ни одной подсказки. Я могу лишь случайно угадать."
    if re.search(r"\b(?:почему|откуда|как)\b",q) and (re.search(r"так (?:быстро|мгновенно|скоро) (?:ответ|пиш)|(?:отвеч|пиш)\w*.{0,12}(?:быстро|мгновенно)|вопрос заранее",q)):
        return "Первое, что пришло в голову, сразу и написал. Над ответом подлиннее я бы посидел."
    if re.search(r"\bпровер\w*\b",q) and re.search(r"тво\w* ответ|тво\w* слов|ты (?:человек|прав)|верить тебе",q):
        return "Я бы проверил конкретные факты: числа пересчитал, а для цитаты нашёл исходный текст. Интонацию проверить гораздо труднее."
    return None
